import test from 'node:test';
import assert from 'node:assert/strict';
import {PAGE_SIZE,REVIEW_LIMIT,REVIEW_KEY,metric,percentage,measuredSummary,validateQA,validateScore,validateSample,readJSONL,joinScores,pageRows,restoreReviews,saveReview,exportReviews,mountEvals} from './app.js';
const enc=new TextEncoder(),cohorts=['train','validation','test'];
// Test fixtures only. Production reports are generated by the offline evaluator.
const qa=index=>({id:'card-'+index,question:'Question '+index,reference:index===64?'A unique reference-only needle':'Reference '+index,source_split:'train',frozen_sft_split:cohorts[index%3],source_group_id:'group-'+index,qa_sha256:index.toString(16).padStart(64,'0')});
const score=index=>({id:'card-'+index,frozen_sft_split:cohorts[index%3],target_tokens:8,full_target_tokens:10,truncated:true,rhys_nll:1.25,qwen_base_nll:1.5});
const sample=index=>({...qa(index),input_tokens:24,rhys:{text:'Rhys output '+index,normalized_exact_match:false,token_f1:0.5,seconds:0.2},qwen_base:{text:'Base output '+index,normalized_exact_match:true,token_f1:1,seconds:0.3}});
const summary=()=>({status:'measured',input_records:3,scored_records:3,skipped:[],checkpoint_run_id:'test-run',weights_sha256:'a'.repeat(64),base_model_id:'test-base',base_revision:'b'.repeat(40),elapsed_seconds:2,cohorts:Object.fromEntries(cohorts.map(name=>[name,{count:1,target_tokens:8,rhys_nll:1.25,qwen_base_nll:1.5,rhys_lower_loss:1,base_lower_loss:0,ties:0}])),generation:{count:3,rhys:{exact_match:0,token_f1:0.5},qwen_base:{exact_match:1,token_f1:1}}});
const manifest={counts:{all_released_records:20923,eligible_qa:18363,missing_reference:2531,missing_question:29},cohorts:{train:16534,validation:923,test:906}};
const jsonl=rows=>new Response(rows.map(row=>JSON.stringify(row)).join('\n'),{headers:{'Content-Type':'application/x-ndjson'}});
const review=(index=0,patch={})=>({id:'card-'+index,qa_sha256:qa(index).qa_sha256,weights_sha256:'a'.repeat(64),checkpoint_run_id:'test-run',choice:'rhys_correct',correction:'',reviewed_at:'2026-10-20T12:00:00.000Z',...patch});

test('unmeasured or absent results never become invented zero metrics',()=>{
  for(const value of [undefined,null,NaN,-1,'0'])assert.equal(metric(value),'—');assert.equal(metric(0),'0.000');assert.equal(percentage(undefined),'—');assert.equal(percentage(0),'0.0%');assert.equal(percentage(2),'—');
  assert.equal(measuredSummary({status:'pending',scored_records:0}),null);assert.equal(measuredSummary({...summary(),weights_sha256:''}),null);assert.equal(measuredSummary(summary()).checkpoint_run_id,'test-run');
});
test('QA, paired loss and generation validators preserve cohort metadata and reject missing or malformed values',()=>{
  assert.equal(validateQA(qa(2)).frozen_sft_split,'test');assert.equal(validateQA(qa(2)).source_split,'train');assert.equal(validateQA({...qa(2),source_has_images:true}).source_has_images,true);assert.equal(validateSample({...sample(0),rhys:{...sample(0).rhys,text:''}}).rhys.text,'');assert.equal(validateScore(score(1)).truncated,true);assert.equal(validateSample(sample(1)).qwen_base.normalized_exact_match,true);
  for(const patch of [{reference:''},{qa_sha256:'wrong'},{frozen_sft_split:'invented'}])assert.throws(()=>validateQA({...qa(0),...patch}));
  for(const patch of [{rhys_nll:null},{qwen_base_nll:-1},{truncated:'yes'},{full_target_tokens:1}])assert.throws(()=>validateScore({...score(0),...patch}));
  assert.throws(()=>validateSample({...sample(0),rhys:{...sample(0).rhys,normalized_exact_match:1}}));assert.throws(()=>validateSample({...sample(0),qwen_base:{...sample(0).qwen_base,token_f1:2}}));
  assert.throws(()=>joinScores([qa(0)],[{...score(0),frozen_sft_split:'test'}]),/split disagree/);assert.equal(joinScores([qa(0)],[])[0].score,null);
});
test('JSONL parser supports split UTF8 and final lines, rejects duplicates and bounds, and aborts finite readers',async()=>{
  const raw=enc.encode(JSON.stringify({...qa(0),question:'café 🌱'})+'\n'+JSON.stringify(qa(1))),response=new Response(new ReadableStream({start(c){for(const byte of raw)c.enqueue(new Uint8Array([byte]));c.close();}}));
  const rows=await readJSONL(response,{validate:validateQA});assert.equal(rows.length,2);assert.equal(rows[0].question,'café 🌱');
  await assert.rejects(()=>readJSONL(jsonl([qa(0),qa(0)]),{validate:validateQA}),/duplicate/);await assert.rejects(()=>readJSONL(jsonl([qa(0),qa(1)]),{validate:validateQA,maxRecords:1}),/record limit/);await assert.rejects(()=>readJSONL(jsonl([qa(0)]),{validate:validateQA,maxBytes:20}),/download limit/);await assert.rejects(()=>readJSONL(new Response('not JSON'),{validate:validateQA}));
  let cancelled=false;const controller=new AbortController(),pending=readJSONL(new Response(new ReadableStream({cancel(){cancelled=true;}})),{validate:validateQA,signal:controller.signal});controller.abort();await assert.rejects(pending,{name:'AbortError'});assert.equal(cancelled,true);
});
test('search covers references and frozen cohorts; pagination is always bounded at30 even for18363cards',()=>{
  const rows=Array.from({length:18363},(_,index)=>qa(index));assert.equal(PAGE_SIZE,30);assert.equal(pageRows(rows).rows.length,30);assert.equal(pageRows(rows,{page:999999}).rows.length,3);assert.equal(pageRows(rows,{page:-1}).page,0);
  const found=pageRows(rows,{query:'reference-only needle'});assert.equal(found.total,1);assert.equal(found.rows[0].id,'card-64');const split=pageRows(rows,{cohort:'test',page:5});assert.equal(split.rows.length,30);assert(split.rows.every(row=>row.frozen_sft_split==='test'));
});
test('compact reviews are capped at200KiB; export joins only matching public samples and checkpoint, never stale answers',()=>{
  let reviews=saveReview([],review(0,{question:'must not be stored',rhys_answer:'must not be stored',correction:'Reviewer correction'}));const stored=JSON.stringify({version:1,entries:reviews});assert(!stored.includes('must not be stored'));assert.equal(restoreReviews(stored).length,1);reviews=saveReview(reviews,review(0,{choice:'both'}));assert.equal(reviews.length,1);assert.equal(reviews[0].choice,'both');
  reviews=saveReview(reviews,review(1,{weights_sha256:'d'.repeat(64)}));const output=exportReviews(reviews,[validateSample(sample(0)),validateSample(sample(1))],summary());const row=JSON.parse(output);assert.equal(row.question,'Question 0');assert.equal(row.rhys_answer,'Rhys output 0');assert.equal(row.qwen_base_answer,'Base output 0');assert.equal(row.choice,'both');assert.equal(output.split('\n').length,1);assert.equal(exportReviews(reviews,[{...validateSample(sample(0)),qa_sha256:'f'.repeat(64)}],summary()),'');assert.equal(exportReviews(reviews,[validateSample(sample(0))],{status:'pending'}),'');
  assert.equal(restoreReviews('x'.repeat(REVIEW_LIMIT+1)).length,0);assert.equal(restoreReviews('{bad JSON').length,0);assert.throws(()=>saveReview([],review(0,{choice:'invalid'})));assert.throws(()=>saveReview([],review(0,{correction:'x'.repeat(2001)})));
  let bounded=[],rejected=false;for(let index=0;index<40;index++){try{bounded=saveReview(bounded,review(index,{correction:'🌱'.repeat(1900)}));}catch(error){assert.match(error.message,/200 KiB/);rejected=true;break;}}assert.equal(rejected,true);assert(enc.encode(JSON.stringify({version:1,entries:bounded})).length<=REVIEW_LIMIT);
});
class Element {
  constructor(tag='div'){this.tagName=tag;this.children=[];this.value='';this.textContent='';this.hidden=false;this.disabled=false;this.events={};this.attrs={};this.style={};this.classList={toggle(){}};}
  addEventListener(name,fn){(this.events[name]||=[]).push(fn);}async fire(name,event={}){for(const fn of this.events[name]||[])await fn({preventDefault(){},...event});}append(...nodes){this.children.push(...nodes);}appendChild(node){this.children.push(node);return node;}replaceChildren(...nodes){this.children=nodes;}setAttribute(name,value){this.attrs[name]=value;}click(){this.clicked=true;}set innerHTML(_){throw Error('HTML rendering forbidden');}
}
function dom(storage=new Map()){
  const ids=Object.fromEntries(['status','all_released_records','eligible_qa','missing_reference','missing_question','summary-table','generation-table','measured','pending','identity','base-identity','coverage','generation-count','query','cohort','qa-rows','qa-count','previous','next','review-count','export-reviews','clear-reviews','samples','sample-page','sample-previous','sample-next','load-qa','load-samples','review-download'].map(name=>[name,new Element()]));
  const urls=[],revoked=[],doc={getElementById:name=>ids[name],createElement:tag=>new Element(tag)},win={localStorage:{getItem:key=>storage.get(key)||null,setItem:(key,value)=>storage.set(key,value),removeItem:key=>storage.delete(key)},URL:{createObjectURL:blob=>{const url='blob:eval-'+urls.length;urls.push({url,blob});return url;},revokeObjectURL:url=>revoked.push(url)},addEventListener(){}};return{ids,doc,win,urls,revoked,storage};
}
test('actual mount fetches onlymanifest+summary bydefault and handles missing report as evaluationinprogress with no fabricated metrics',async(t)=>{
  const d=dom(),calls=[];const app=mountEvals(d.doc,d.win,async(url,init)=>{calls.push({url,init});return url.endsWith('manifest.json')?Response.json(manifest):new Response('not ready',{status:404});});t.after(()=>app.dispose());await app.initialized;
  assert.deepEqual(calls.map(call=>call.url).sort(),['./data/manifest.json','./data/summary.json']);assert.equal(d.ids.measured.hidden,true);assert.equal(d.ids.pending.hidden,false);assert.match(d.ids.pending.textContent,/Evaluation in progress/);assert.equal(d.ids['summary-table'].children.length,0);assert.equal(d.ids['generation-table'].children.length,0);assert.equal(d.ids.eligible_qa.textContent,'18,363');assert.equal(d.ids['qa-rows'].children.length,0);assert(calls.every(call=>!call.init.method));
});
test('generated answer agreement keeps held-out cohorts separate from the combined sample',async(t)=>{
  const d=dom(),measured=summary();measured.generation.by_cohort={test:{count:1,rhys:{exact_match:1,token_f1:1},qwen_base:{exact_match:0,token_f1:0}}};
  const app=mountEvals(d.doc,d.win,async url=>Response.json(url.endsWith('manifest.json')?manifest:measured));t.after(()=>app.dispose());await app.initialized;const rows=d.ids['generation-table'].children;assert.equal(rows.length,4);assert.match(rows[2].children[0].textContent,/test.*Rhys adaptation.*1 pairs/);assert.equal(rows[0].children[1].textContent,'0.0%');assert.equal(rows[2].children[1].textContent,'100.0%');
});
test('explicit allQA loads scores and cards once, renders max30rows, preserves truncation and shows unscoredloss asdash',async(t)=>{
  const d=dom(),calls=[],cards=Array.from({length:65},(_,index)=>qa(index));
  const app=mountEvals(d.doc,d.win,async(url,init)=>{calls.push({url,init});if(url.endsWith('manifest.json'))return Response.json(manifest);if(url.endsWith('summary.json'))return Response.json(summary());if(url.endsWith('anki.jsonl'))return jsonl(cards);if(url.endsWith('scores.jsonl'))return jsonl(cards.filter((_,index)=>index%2).map((_,index)=>score(index*2+1)));throw Error('Unexpected fetch');});t.after(()=>app.dispose());await app.initialized;assert.equal(calls.length,2);assert.equal(d.ids['summary-table'].children.length,3);assert.equal(d.ids['generation-table'].children[0].children[1].textContent,'0.0%','an actual measured zero stays zero');
  await d.ids['load-qa'].fire('click');assert.equal(calls.length,4);assert.equal(d.ids['qa-rows'].children.length,30);assert.equal(d.ids['qa-rows'].children[0].children[2].textContent,'—');assert.equal(d.ids['qa-rows'].children[0].children[5].textContent,'Not scored');assert.equal(d.ids['qa-rows'].children[1].children[5].textContent,'Yes');assert.equal(d.ids['qa-rows'].children[1].children[4].textContent,'8 / 10');
  await d.ids.next.fire('click');assert.equal(d.ids['qa-rows'].children.length,30);await d.ids.next.fire('click');assert.equal(d.ids['qa-rows'].children.length,5);d.ids.query.value='reference-only needle';await d.ids.query.fire('input');assert.equal(d.ids['qa-rows'].children.length,1);assert.equal(d.ids['qa-rows'].children[0].children[0].children[0].textContent,'Question 64');d.ids.query.value='';d.ids.cohort.value='test';await d.ids.cohort.fire('change');assert(d.ids['qa-rows'].children.every(row=>row.children[1].textContent==='test'));assert.equal(calls.length,4,'pagination/search/filter must not make additional calls');await d.ids['load-qa'].fire('click');assert.equal(calls.length,4);
});
test('actual public answer review saves compact local labels, reveals references, exports full publicdata and supportsdelete/clearwithoutPOST',async(t)=>{
  const d=dom(),calls=[];
  const app=mountEvals(d.doc,d.win,async(url,init)=>{calls.push({url,init});if(url.endsWith('manifest.json'))return Response.json(manifest);if(url.endsWith('summary.json'))return Response.json(summary());if(url.endsWith('samples.jsonl'))return jsonl(Array.from({length:5},(_,index)=>sample(index)));throw Error('Unexpected fetch');});t.after(()=>app.dispose());await app.initialized;await d.ids['load-samples'].fire('click');assert.equal(calls.length,3);assert.equal(d.ids.samples.children.length,4);const article=d.ids.samples.children[0];assert.equal(article.children[2].children.length,2);assert.equal(article.children[3].children[0].textContent,'Reveal reference card');assert.equal(article.children[3].children[1].textContent,'Reference 0');assert.match(article.children[2].children[0].children[2].textContent,/Normalized exact match: no · token F1: 0.500/);
  const controls=article.children[4];await controls.children[0].children[0].fire('click');controls.children[1].value='Correct this explanation';await controls.children[2].fire('click');const stored=d.storage.get(REVIEW_KEY);assert(stored.includes('Correct this explanation'));assert(!stored.includes('Question 0'));assert(!stored.includes('Rhys output'));assert.equal(enc.encode(stored).length<REVIEW_LIMIT,true);
  await d.ids['export-reviews'].fire('click');assert.equal(calls.length,3);assert.equal(d.ids['review-download'].clicked,true);const exported=JSON.parse(await d.urls.at(-1).blob.text());assert.equal(exported.question,'Question 0');assert.equal(exported.reference,'Reference 0');assert.equal(exported.rhys_answer,'Rhys output 0');assert.equal(exported.qwen_base_answer,'Base output 0');assert.equal(exported.correction,'Correct this explanation');assert.equal(exported.weights_sha256,summary().weights_sha256);
  await d.ids['sample-next'].fire('click');assert.equal(d.ids.samples.children.length,1);await d.ids['sample-previous'].fire('click');await d.ids.samples.children[0].children[4].children[3].fire('click');assert.equal(restoreReviews(d.storage.get(REVIEW_KEY)).length,0);await d.ids.samples.children[1].children[4].children[0].children[4].fire('click');assert.equal(restoreReviews(d.storage.get(REVIEW_KEY)).length,1);await d.ids['clear-reviews'].fire('click');assert.equal(d.storage.has(REVIEW_KEY),false);assert.equal(d.ids['export-reviews'].disabled,true);assert.equal(calls.length,3);assert(calls.every(call=>!call.init.method));
});
